<main class="mx-auto max-w-4xl px-4 py-9 pb-28 sm:px-6 lg:px-8 md:pb-12">
  <div class="flex items-end justify-between gap-3"><div><p class="text-[10px] font-black uppercase tracking-[.2em] text-violet-300">Player inbox</p><h1 class="mt-2 text-3xl font-black">Notifications</h1><p class="mt-2 text-sm text-slate-400">Registrations, invitations, room access, match results, deposits and withdrawals.</p></div><?php if($unreadCount): ?><span class="badge badge-soon"><?= h($unreadCount) ?> unread</span><?php endif; ?></div>
  <?php if (!$notifications): ?><div class="glass-card mt-6 rounded-2xl p-10 text-center"><i class="fa-regular fa-bell text-2xl text-violet-300" aria-hidden="true"></i><h2 class="mt-4 font-black">You’re all caught up</h2><p class="mt-2 text-xs text-slate-500">Important tournament updates will show here.</p></div><?php else: ?>
    <div class="mt-6 space-y-3"><?php foreach($notifications as $item): ?><article class="glass-card rounded-2xl p-4 <?= $item['read_at']?'opacity-75':'' ?>"><div class="flex items-start justify-between gap-4"><div class="flex gap-3"><span class="mt-1 grid h-8 w-8 shrink-0 place-items-center rounded-lg <?= $item['read_at']?'bg-white/[.06] text-slate-500':'bg-violet-500/10 text-violet-300' ?>"><i class="fa-solid <?= $item['notification_type']==='results'?'fa-ranking-star':($item['notification_type']==='deposit'?'fa-wallet':($item['notification_type']==='invitation'?'fa-user-plus':'fa-bell')) ?>" aria-hidden="true"></i></span><div><h2 class="text-sm font-black"><?= h($item['title']) ?></h2><p class="mt-1 text-xs leading-5 text-slate-400"><?= h($item['body']) ?></p><p class="mt-2 text-[10px] text-slate-600"><?= h(date('d M Y · g:i A',strtotime((string)$item['created_at'].' UTC'))) ?> IST</p></div></div><div class="flex shrink-0 flex-col items-end gap-2"><?php if($item['target_url']): ?><a class="text-[10px] font-bold text-violet-300" href="<?= h(app_url($item['target_url'])) ?>">Open</a><?php endif; ?><?php if(!$item['read_at']): ?><form method="post" action="<?= h(app_url('index.php?action=notification-read')) ?>"><?= csrf_field() ?><input type="hidden" name="notification_id" value="<?= h($item['id']) ?>"><button class="text-[10px] font-bold text-slate-500 hover:text-white">Mark read</button></form><?php endif; ?></div></div></article><?php endforeach; ?></div>
  <?php endif; ?>
</main>
